// secrets-veil: tree.test.ts - unit tests for render tree walker
// Generated by OrchestKit mod build

import { describe, it, expect } from "vitest";
import { buildOverlayTree, walkAndMask, isTextNode, isBoxNode } from "../src/tree.ts";
import type { MaskSpan, RenderNode } from "../src/types.ts";

describe("tree module", () => {
  describe("buildOverlayTree", () => {
    it("returns single text node when no spans", () => {
      const nodes = buildOverlayTree("plain text", [], "req-1");
      expect(nodes.length).toBe(1);
      expect(nodes[0].type).toBe("Text");
    });

    it("creates overlay for single span", () => {
      const spans: MaskSpan[] = [
        { start: 7, end: 17, value: "secret123" },
      ];
      const nodes = buildOverlayTree("prefix secret123 suffix", spans, "req-1");

      // Should have: prefix text, masked box, suffix text
      expect(nodes.length).toBe(3);
      expect(nodes[0].type).toBe("Text");
      expect(nodes[1].type).toBe("Box");
      expect(nodes[2].type).toBe("Text");
    });

    it("creates keyed boxes for multiple spans", () => {
      const spans: MaskSpan[] = [
        { start: 0, end: 9, value: "secret123" },
        { start: 15, end: 24, value: "token456" },
      ];
      const nodes = buildOverlayTree("secret123 mid token456 end", spans, "req-1");

      // First and third should be Box (masked), second is Text " mid "
      expect(nodes[0].type).toBe("Box");
      expect(nodes[1].type).toBe("Text");
      expect(nodes[2].type).toBe("Box");
      expect(nodes[3].type).toBe("Text");
    });

    it("includes hover display none/flex structure", () => {
      const spans: MaskSpan[] = [
        { start: 0, end: 9, value: "secret123" },
      ];
      const nodes = buildOverlayTree("secret123", spans, "req-1");
      const box = nodes[0];
      expect(box.type).toBe("Box");
      if (box.type === "Box" && box.children) {
        // First child is masked text, second is hover-reveal Box
        expect(box.children.length).toBe(2);
        const revealBox = box.children[1];
        expect(revealBox.type).toBe("Box");
        if (revealBox.type === "Box" && revealBox.props) {
          expect(revealBox.props.display).toBe("none");
          expect(revealBox.props.hover).toEqual({ display: "flex" });
        }
      }
    });

    it("uses unique keys per request and span", () => {
      const spans: MaskSpan[] = [
        { start: 0, end: 5, value: "sec1" },
        { start: 6, end: 11, value: "sec2" },
      ];
      const nodes = buildOverlayTree("sec1 sec2", spans, "req-abc");
      const keys = nodes
        .filter((n) => n.type === "Box" && n.props?.key)
        .map((n) => (n as { type: "Box"; props: { key: string } }).props.key);

      expect(keys).toContain("veil-req-abc-0");
      expect(keys).toContain("veil-req-abc-1");
    });
  });

  describe("walkAndMask", () => {
    it("returns original tree when no spans", () => {
      const tree: RenderNode = { type: "Text", props: { children: "plain" } };
      const result = walkAndMask(tree, []);
      expect(result).toEqual(tree);
    });

    it("wraps tree in overlay when spans present", () => {
      const tree: RenderNode = {
        type: "ToolResult",
        props: { requestId: "req-1" },
        children: [{ type: "Text", props: { children: "secret123" } }],
      };
      const spans: MaskSpan[] = [
        { start: 0, end: 9, value: "secret123" },
      ];
      const result = walkAndMask(tree, spans);
      expect(result.type).toBe("Box");
      if (result.type === "Box" && result.children) {
        expect(result.children.length).toBeGreaterThan(0);
      }
    });
  });

  describe("isTextNode / isBoxNode", () => {
    it("identifies text nodes", () => {
      const node = { type: "Text", props: { children: "text" } };
      expect(isTextNode(node)).toBe(true);
      expect(isBoxNode(node)).toBe(false);
    });

    it("identifies box nodes", () => {
      const node = { type: "Box", props: { key: "k1" }, children: [] };
      expect(isBoxNode(node)).toBe(true);
      expect(isTextNode(node)).toBe(false);
    });

    it("returns false for unknown types", () => {
      const node = { type: "Unknown", props: {} };
      expect(isTextNode(node)).toBe(false);
      expect(isBoxNode(node)).toBe(false);
    });
  });
});
